import { invoke } from "@tauri-apps/api/core";
export interface PdfParseResult {
  /** 是否解析成功 */
  success: boolean;
  /** 高保真 GFM Markdown 完整文本内容 */
  markdown: String;
  /** 本地生成的 Markdown 物理绝对路径 */
  output_md_path: string;
  /** 任务专属产物根目录物理路径 */
  task_out_dir: string;
  /** 图片资源物理目录 (task_out_dir/images) */
  images_dir: string;
