    } catch {
      await navigator.clipboard.writeText(target);
      ui.弹出提示('已复制文件路径到剪贴板', 'info');
    }
  };
  const closeSuccessModal = () => {
    isSuccessModalOpen.value = false;
  };
  return {
    state,
    queue,
    isDragging,
    activeIndex,
    progress,
    statusText,
    elapsedMs,
    errorMessage,
    isProcessingModalOpen,
    isSuccessModalOpen,
    successInfo,
    latestResults,
    fileInputRef,
    triggerFileSelect,
    addFiles,
    addPaths,
    removeFile,
    clearQueue,
    handleFileChange,
    handleDragOver,
    handleDragLeave,
    handleDrop,
    executeBatch,
    cancelProcessing,
    openFolder,
    closeSuccessModal,
  };
