#[tauri::command]
fn cancel_current_task(state: State<'_, AppState>) -> Result<bool, String> {
    log::warn!("🛑 [IPC] 收到前端紧急任务截停指令");
    state.cancel_token.store(true, Ordering::SeqCst);
    Ok(true)
}
#[tauri::command]
fn get_hardware_fingerprint() -> Result<String, String> {
    let secret = "ai-forge-commercial-secret-2026";
    DeviceFingerprint::new()
        .add_cpu_info()
        .add_mac_address()
        .add_system_info()
        .generate(secret)
        .map_err(|e| e.to_string())
}
#[tauri::command]
async fn run_format_convert(
    task: FormatConvertTask,
    window: tauri::Window,
) -> Result<FormatConvertResult, String> {
    log::info!("🚀 [格式转换] 启动转换: 源文件='{}', 目标格式='{}'", task.input_path, task.target_format);
    let res = FormatConvertService::convert(&task);
    let _ = window.emit("format-convert-finished", &res);
    Ok(res)
}
#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    PortableEngine::init();
    core_onnx_infer::config::ensure_cuda_dll_registered();
    let logs_dir = resolve_log_dir_path();
    let output_dir = PortableEngine::resolve_data_path("outputs")
        .unwrap_or_else(|| std::env::temp_dir().join("ai_forge_outputs"));
    let _ = std::fs::create_dir_all(&output_dir);
    let app_state = AppState {
        vram_guard: Arc::new(VramTokenGuard::default_rtx3060()),
        output_dir,
        cancel_token: Arc::new(AtomicBool::new(false)),
    };
    let log_plugin = LogBuilder::new()
        .level(log::LevelFilter::Info)
        .max_file_size(5_000_000)
        .rotation_strategy(RotationStrategy::KeepOne)
        .clear_targets()
        .targets([
            Target::new(TargetKind::Stdout),
            Target::new(TargetKind::Folder {
                path: logs_dir.clone(),
                file_name: Some("zidian".into()),
            }),
        ])
        .build();
    tauri::Builder::default()
        .plugin(tauri_plugin_opener::init())
        .plugin(tauri_plugin_dialog::init())
        .plugin(tauri_plugin_process::init())
        .plugin(log_plugin)
        .plugin(tauri_plugin_updater::Builder::new().build())
        .manage(app_state)
        .invoke_handler(tauri::generate_handler![
            is_portable,
            get_quota_status,
            get_log_dir_path,
            open_log_dir,
            get_diagnostic_report,
            parse_pdf,
            probe_video,
            run_video_subtitle,
            cancel_current_task,
            get_hardware_fingerprint,
            run_format_convert,
            run_upscale_48k,
            check_tool_dependencies,
            download_tool_dependencies,
            cancel_dependency_downloads,
            install_app_update,
            run_translation,
            run_image_translation
        ])
        .setup(move |_app| {
            log::info!("======================================================================");
            log::info!("🚀 [紫电 AI] 工业级桌面工坊已点火启动 (生产黑匣子日志已就绪)");
            log::info!("📁 [日志物理目录] {}", clean_path_str(&logs_dir));
            log::info!("🖥️ [系统环境] OS: {} | Arch: {}", std::env::consts::OS, std::env::consts::ARCH);
            log::info!("======================================================================\n");
            Ok(())
        })
        .run(tauri::generate_context!())
        .expect("🚨 启动 紫电 AI 桌面端失败");
}[package]
name = "ai-forge"
version = "0.1.0"
description = "AI-Forge Desktop App"
edition = "2021"

[lib]
name = "ai_forge_lib"
path = "src/lib.rs"

[build-dependencies]
tauri-build = { version = "2.0.0", features = [] }

[dependencies]
tauri = { version = "2.0.0", features = [] }
tauri-plugin-opener = "2.0.0"
tauri-plugin-dialog = "2.0.0"
tauri-plugin-updater = "2.0.0"
tauri-plugin-process = "2.0.0"
tauri-plugin-log = "2.0.0"
log = "0.4"
tracing = "0.1"
tracing-log = "0.2"
serde = { version = "1.0", features = ["derive"] }
serde_json = "1.0"
shared-contracts = { path = "crates/shared-contracts" }
core-models-download = { path = "crates/core-models-download" }
pdf-parse = { path = "crates/tools/pdf-parse" }
core-security = { path = "crates/core-security" }
service-asr = { path = "crates/services/service-asr" }
service-translation = { path = "crates/services/service-translation" }
service-layout = { path = "crates/services/service-layout" }
service-formula = { path = "crates/services/service-formula" }
service-table = { path = "crates/services/service-table" }
service-doc-parse = { path = "crates/services/service-doc-parse" }
service-pdfium = { path = "crates/services/service-pdfium" }
service-converter = { path = "crates/services/service-converter" }
format-converter = { path = "crates/tools/format-converter" }
video-subtitle = { path = "crates/tools/video-subtitle" }
service-upscale = { path = "crates/services/service-upscale" }
upscale-48k = { path = "crates/tools/upscale-48k" }
core-onnx-infer = { path = "crates/core-onnx-infer" }
translation = { path = "crates/tools/translation" }

[workspace]
members = [
    ".",
    "crates/core-ipc",
    "crates/core-security",
    "crates/core-models-download",
    "crates/shared-contracts",
    "crates/core-onnx-infer",
    "crates/services/service-asr",
    "crates/services/service-translation",
    "crates/services/service-layout",
    "crates/services/service-formula",
    "crates/services/service-table",
    "crates/services/service-doc-parse",
    "crates/services/service-pdfium",
    "crates/services/service-converter",
    "crates/tools/pdf-parse",
    "crates/tools/format-converter",
    "crates/tools/video-subtitle",
    "crates/tools/upscale-48k",
    "crates/tools/translation",
    "crates/services/service-ocr",
    "crates/services/service-upscale"
]
resolver = "2"
